const visual = {
  prepare: function (input) { return [{ kind: 'text', payload: '向下' }]; },
  render: function (input, metrics) {
    var w = input.viewport.widthDu, h = input.viewport.heightDu;
    return { schemaVersion: 1, sceneId: 'cal', revision: input.revision,
             viewBox: { x: 0, y: 0, width: w, height: h },
             paths: [{ id: 'arrow', commands: visualSdk.arrow(180, 60, 180, 200, {}) }],
             root: { type: 'group', children: [
               { type: 'path', pathId: 'arrow', fill: '#26354a', stroke: { width: 3 } }, { type: 'label', contentId: metrics[0].contentId, anchor: { x: 180, y: 40 }, hAlign: 'center', vAlign: 'top', color: '#26354a' } ] } };
  },
};
